    let nextSaved = try adoption.saved?.validated()
    libraryOperation = nextOperation
    editor = nextEditor
    library = adoption.library
    saved = nextSaved
    if adoption.resetsPresentation {
        workspaceResetID = UUID()
        feature = nil
    }
    loaded = true
    saveBlocked = false
